30	import org.springframework.http.converter.HttpMessageConverter;
31	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
32	import org.springframework.web.bind.annotation.ControllerAdvice;
33	import org.springframework.web.bind.annotation.ExceptionHandler;
34	import org.springframework.web.bind.annotation.ResponseBody;
35	import org.springframework.web.servlet.mvc.method.annotation.RequestBodyAdviceAdapter;
36	
37	/**
38	 * Rejects an owner whose required text fields are missing or blank before the request
39	 * reaches the controller, answering with a 400 and an {@code errors} array naming each
40	 * offending field. Kept separate from the general {@link ExceptionControllerAdvice} so
41	 * neither this rule nor the existing handlers grow to accommodate the other.
42	 */
43	@ControllerAdvice
44	@Order(Ordered.HIGHEST_PRECEDENCE)
45	public class OwnerFieldsValidationAdvice extends RequestBodyAdviceAdapter {
46	
47	    @Override
48	    public boolean supports(MethodParameter methodParameter, Type targetType,
49	                            Class<? extends HttpMessageConverter<?>> converterType) {
50	        return OwnerFieldsDto.class.equals(targetType);
51	    }
52	
53	    @Override
54	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
55	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
56	        List<String> missing = missingFields((OwnerFieldsDto) body);
57	        if (!missing.isEmpty()) {
58	            throw new MissingOwnerFieldsException(missing);
59	        }
60	        return body;
61	    }
62	
63	    private List<String> missingFields(OwnerFieldsDto owner) {
64	        List<String> missing = new ArrayList<>();
65	        addIfBlank(missing, "firstName", owner.getFirstName());
66	        addIfBlank(missing, "lastName", owner.getLastName());
67	        addIfBlank(missing, "address", owner.getAddress());
68	        addIfBlank(missing, "city", owner.getCity());
69	        addIfBlank(missing, "telephone", owner.getTelephone());
70	        return missing;
71	    }
72	
73	    private void addIfBlank(List<String> missing, String field, String value) {
74	        if (value == null || value.isBlank()) {
75	            missing.add(field);
76	        }
77	    }
78	
79	    @ExceptionHandler(MissingOwnerFieldsException.class)
80	    @ResponseBody
81	    public ResponseEntity<Map<String, List<String>>> handleMissingOwnerFields(MissingOwnerFieldsException e) {
82	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(Map.of("errors", e.getMissingFields()));
83	    }
84	
85	    /** Carries the names of the owner fields that were missing or blank. */
86	    static class MissingOwnerFieldsException extends RuntimeException {
87	
88	        private final transient List<String> missingFields;
89	
90	        MissingOwnerFieldsException(List<String> missingFields) {
91	            this.missingFields = missingFields;
92	        }
93	
94	        List<String> getMissingFields() {
95	            return this.missingFields;
96	        }
97	    }
98	}
